/**
 * @param {string} language
 */
function getBaseLanguage(language) {
  return language.replace('_', '-').toLowerCase().split('-')[0]
}

/**
 * @param {string} languageA
 * @param {string} languageB
 */
export function isSameBaseLanguage(languageA, languageB) {
  return getBaseLanguage(languageA) === getBaseLanguage(languageB)
}

/**
 * YouTube adds an auto-generated caption track for every AI-dubbed audio track,
 * which transcribes the machine dub instead of the original speech.
 * Only call this for auto-generated tracks.
 * @param {string} language
 * @param {string | null | undefined} originalLanguage the language of the original audio track
 * @param {string[]} autoGeneratedLanguages the languages of all auto-generated tracks
 */
export function isDubbedCaptionLanguage(language, originalLanguage, autoGeneratedLanguages) {
  // Without an original language transcript, a mismatch is more likely wrong metadata than a dub
  return !!originalLanguage && !isSameBaseLanguage(language, originalLanguage) &&
    autoGeneratedLanguages.some(other => isSameBaseLanguage(other, originalLanguage))
}

/**
 * Finds the caption that most closely matches the preferred locale.
 * @template {{ language: string }} T
 * @param {T[]} captions
 * @param {string} preferredLocale
 * @returns {T | null}
 */
export function findCaptionByLocale(captions, preferredLocale) {
  const normalizedLocale = preferredLocale.replace('_', '-').toLowerCase()

  return captions.find(caption => caption.language.replace('_', '-').toLowerCase() === normalizedLocale) ??
    captions.find(caption => isSameBaseLanguage(caption.language, normalizedLocale)) ??
    null
}

/**
 * Selects the caption that should be enabled by default.
 * Transcripts of dubbed audio are never picked, as they are machine translations of lower quality.
 * @template {{ language: string, isAutotranslated?: boolean, isDubbed?: boolean }} T
 * @param {T[]} captions
 * @param {string} preferredLocale
 * @param {boolean} enableCaptionTranslations
 * @returns {T | null}
 */
export function getPreferredCaption(captions, preferredLocale, enableCaptionTranslations) {
  const selectableCaptions = captions.filter(caption =>
    !caption.isDubbed && (enableCaptionTranslations || !caption.isAutotranslated)
  )

  return findCaptionByLocale(selectableCaptions, preferredLocale) ?? selectableCaptions[0] ?? null
}

/**
 * Picks the YouTube caption track to machine translate.
 * @template {{ kind?: string, language_code: string, is_translatable: boolean }} T
 * @param {T[]} captionTracks
 * @param {string | null | undefined} originalLanguage the language of the original audio track, if known
 * @returns {T | undefined}
 */
export function getCaptionTranslationSource(captionTracks, originalLanguage) {
  // Dubbed videos have an auto-generated track per audio track, so prefer the original speech
  const autoGeneratedCaptionTrack = (originalLanguage &&
    captionTracks.find(track => track.kind === 'asr' && isSameBaseLanguage(track.language_code, originalLanguage))) ||
    captionTracks.find(track => track.kind === 'asr')

  if (autoGeneratedCaptionTrack) {
    // A user uploaded caption track in the language of the video is more trustworthy than auto-generated captions
    return captionTracks.find(track => track.kind !== 'asr' && track.language_code === autoGeneratedCaptionTrack.language_code) ??
      autoGeneratedCaptionTrack
  }

  // if there is no auto-generated track choose the first translatable track
  return captionTracks.find(track => track.is_translatable) ?? captionTracks[0]
}
